@dataclass
class Agent(AgentBase, Generic[TContext]):
    """An agent is an AI model configured with instructions, tools, guardrails, handoffs and more.

    We strongly recommend passing `instructions`, which is the "system prompt" for the agent..."""

async def get_system_prompt(self, run_context: RunContextWrapper[TContext]) -> str | None:
    if isinstance(self.instructions, str):
        return self.instructions
    elif callable(self.instructions):
        sig = inspect.signature(self.instructions)
        params = list(sig.parameters.values())
        if len(params) != 2:
            raise TypeError(
                f"'instructions' callable must accept exactly 2 arguments (context, agent), ...")
        result = self.instructions(run_context, self)
        if inspect.isawaitable(result):
            return await result
        return result

